import { ChecklistRoot } from "@/components/bevelui/checklist";
import type { ChecklistStep } from "@/components/bevelui/checklist";

const steps: ChecklistStep[] = [
  {
    id:          "profile",
    title:       "Complete your profile",
    description: "Add your name and avatar.",
    cta:         "Edit profile",
    onAction:    () => router.push("/settings/profile"),
  },
  {
    id:          "project",
    title:       "Create your first project",
    cta:         "New project",
    onAction:    () => openNewProjectModal(),
  },
  {
    id:          "invite",
    title:       "Invite a teammate",
    cta:         "Invite",
    requires:    ["project"],    // locked until project is done
    onAction:    () => openInviteModal(),
  },
  {
    id:          "deploy",
    title:       "Deploy to production",
    cta:         "Deploy",
    requires:    ["project"],
    optional:    true,           // skippable, doesn't block completion
    onAction:    () => router.push("/deploy"),
  },
];

export default function Layout({ children }) {
  return (
    <ChecklistRoot
      steps={steps}
      config={{
        title:      "Get started",
        subtitle:   "Complete your setup",
        storageKey: `checklist-${user.id}`,  // namespace per user
      }}
    >
      {children}
    </ChecklistRoot>
  );
}

// This step is locked until both "profile" and "project" are complete
{
  id:       "invite",
  title:    "Invite a teammate",
  requires: ["profile", "project"],
  onAction: () => openInvite(),
}

// Per-user namespace
<ChecklistRoot
  steps={steps}
  config={{ storageKey: `onboarding-${user.id}` }}
>

// To reset programmatically — use useChecklist inside a child
function ResetButton() {
  const { undo, steps } = useChecklist();
  return (
    <button onClick={() => steps.forEach(s => undo(s.id))}>
      Reset progress
    </button>
  );
}

import {
  ChecklistRoot,
  ChecklistItem,
  ChecklistProgressRing,
  useChecklist,
} from "@/components/bevelui/checklist";

function SidebarChecklist() {
  const { steps, progress, completedCount, requiredCount } = useChecklist();
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center gap-2">
        <ChecklistProgressRing progress={progress} size={32} strokeWidth={2} />
        <span>{completedCount}/{requiredCount} complete</span>
      </div>
      {steps.map(step => <ChecklistItem key={step.id} step={step} />)}
    </div>
  );
}

<ChecklistRoot steps={steps} config={{ position: "inline" }}>
  <Sidebar>
    <SidebarChecklist />
  </Sidebar>
</ChecklistRoot>
